import java.util.Scanner;

public class Main {
    static final int MAX = 511;
    static long[][] dwu = new long[MAX][MAX];
    static long[] dp1 = new long[MAX];
    static long[][] dp2 = new long[MAX][MAX];
    static long[][] dp3 = new long[MAX][MAX];
    static long[] cnt = new long[MAX];
    static int n, m, P;

    static void update_self(long[] a, int index, long b) {
        a[index] = (a[index] * b) % P;
    }

    static long multiply(long a, long b) {
        return (a * b) % P;
    }

    static void add_mod(long[] a, int index, long b) {
        a[index] += b;
        if (a[index] >= P) a[index] -= P;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();

        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= i + 1; j++) {
                if (j == 0) {
                    dwu[i][j] = 1;
                } else {
                    dwu[i][j] = dwu[i - 1][j];
                    long val = dwu[i - 1][j - 1];
                    val %= P;
                    dwu[i][j] = (dwu[i][j] + val) % P;
                }
            }
        }

        dp1[0] = 0;
        cnt[0] = 1;
        for (int i = 0; i <= m; i++) {
            if (i > 0) {
                for (int j = 0; j < i; j++) {
                    long val = 0;
                    add_mod(new long[]{val}, 0, multiply(dp1[j], cnt[i - j - 1]));
                    add_mod(new long[]{val}, 0, multiply(dp1[i - j - 1], cnt[j]));
                    update_self(new long[]{val}, 0, j + 1);
                    long tempVal = multiply(multiply(cnt[i - j - 1], cnt[j]), j * (j + 1) / 2);
                    add_mod(new long[]{val}, 0, tempVal);
                    update_self(new long[]{val}, 0, dwu[i - 1][j]);
                    dp1[i] = (dp1[i] + val) % P;

                    long temp = dwu[i - 1][j];
                    temp = (temp * cnt[j]) % P;
                    temp = (temp * cnt[i - j - 1]) % P;
                    temp = (temp * (j + 1)) % P;
                    cnt[i] = (cnt[i] + temp) % P;
                }
                cnt[i] = (cnt[i] + cnt[i]) % P;
                dp1[i] = (dp1[i] + dp1[i]) % P;
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    if (j + k <= m && i + k + 1 <= n + 1) {
                        long val = dp2[i][j];
                        val = (val * dwu[m - j][k]) % P;
                        val = (val * cnt[k]) % P;

                        long val3 = dp3[i][j];
                        val3 = (val3 * cnt[k]) % P;
                        val3 = (val3 + multiply(dp1[k], dp2[i][j])) % P;
                        val3 = (val3 + dwu[m - j][k]) % P;

                        dp3[i + k + 1][j + k] = (dp3[i + k + 1][j + k] + val3) % P;
                        dp2[i + k + 1][j + k] = (dp2[i + k + 1][j + k] + val) % P;
                    }
                }
            }
        }

        System.out.println(dp3[n + 1][m]);
        sc.close();
    }
}
